message.content:
{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "The controller's frequency and gains are mismatched to the creature's body dynamics because the controller was tuned for a lighter torso and longer feet. Dynamic similarity transfer will improve walking.",
      "evidence": [
        "creature.features.torso_frac",
        "creature.reference.features.torso_frac",
        "creature.features.foot_to_leg",
        "creature.reference.features.foot_to_leg",
        "baseline.controller_freq_ratio"
      ],
      "competing": [
        "The controller structure itself is inadequate (e.g., missing foot placement feedback)."
      ]
    },
    {
      "id": "H2",
      "mechanism": "The creature's torso mass is too high relative to leg strength, causing uncontrollable forward pitch divergence. Reducing torso mass (or increasing leg length) will improve survival with the current controller.",
      "evidence": [
        "creature.torso_mass",
        "creature.features.torso_frac",
        "baseline.pitch_drift_radps",
        "baseline.forward_fall_frac"
      ],
      "competing": [
        "The controller's feedback gains are too low to stabilize the heavy torso."
      ]
    },
    {
      "id": "H3",
      "mechanism": "The lack of foot placement feedback (fp_kd, fp_kv = 0) prevents the controller from adjusting foot placement to arrest forward falls, as evidenced by highly negative capture margins.",
      "evidence": [
        "baseline.capture_margin_over_leg_mean",
        "baseline.capture_margin_over_leg_min",
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.touchdown_foot_ahead_trend"
      ],
      "competing": [
        "The stride or timing parameters are poorly tuned, causing poor foot placement regardless of feedback."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "similarity",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "torso_x0_7",
      "hypothesis": "H2",
      "expect": "improves"
    },
    {
      "probe_id": "opt_placement",
      "hypothesis": "H3",
      "expect": "improves"
    }
  ]
}

